import {MAX_WAVES,defaults,sanitize,insideLake,createSources,addSources,pruneWaves} from './model.js';
import {LAKE} from './world.js';
import {vertexShader,fragmentShader} from './water.js';
import {makeGrove} from './grove.js';
import {makeDeer} from './deer.js';
import {makeScenery} from './scenery.js';
import {makeAtmosphere} from './atmosphere.js';
import {makeFarms} from './farms.js';
import {daylightAt,formatWorldTime,DAY_LENGTH} from './daylight.js';
const $=id=>document.getElementById(id);let state={...defaults},waves=[],time=0,paused=false,engine=null,toastTimer,dayOffset=0;
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function sync(){$('wavelength-value').textContent=`${state.wavelength.toFixed(2).replace('.',',')} m`;$('persistence-value').textContent=`${state.persistence.toFixed(1).replace('.',',')} s`;}
for(const key of ['pattern','wavelength','persistence'])$(key).addEventListener('input',()=>{state=sanitize({...state,[key]:key==='pattern'?$(key).value:Number($(key).value)});sync();});sync();
function status(){$('activity').textContent=waves.length?`${waves.length} ${waves.length===1?'fonte ativa':'fontes ativas'}${paused?' · pausa':''}`:'O lago está tranquilo';}
function setPaused(value){paused=value;$('pause').innerHTML=paused?'▶ <span>Continuar</span>':'Ⅱ <span>Pausar</span>';$('pause').setAttribute('aria-pressed',paused);status();}
function explore(){document.body.classList.add('exploring');$('hint').classList.add('hidden');}
$('explore').onclick=()=>{explore();$('scene').focus();toast('Arraste para olhar. Use WASD ou dois dedos para se deslocar.');};
$('home').onclick=()=>{engine?.navigation.home();document.body.classList.remove('exploring');};
$('panel-toggle').onclick=()=>{const hidden=document.body.classList.toggle('panel-collapsed');$('panel-toggle').setAttribute('aria-expanded',!hidden);$('panel-toggle').textContent=hidden?'Ondas +':'Ondas −';};
document.querySelectorAll('[data-move]').forEach(button=>{button.addEventListener('pointerdown',event=>{event.preventDefault();button.setPointerCapture(event.pointerId);engine?.navigation.hold(button.dataset.move,true);});for(const type of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(type,()=>engine?.navigation.hold(button.dataset.move,false));});
$('world-clock').onclick=()=>{dayOffset+=DAY_LENGTH/4;};
$('pause').onclick=()=>setPaused(!paused);$('clear').onclick=()=>{waves=[];engine?.upload();status();};
$('about-open').onclick=()=>{engine?.navigation.clearInput();$('about').showModal();};$('about-close').onclick=()=>$('about').close();$('about').addEventListener('click',event=>{if(event.target===$('about')){const r=$('about').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('about').close();}});
$('export').onclick=()=>{if(!engine){toast('Aguarde a abertura da clareira.');return;}engine.render();engine.canvas.toBlob(blob=>{if(!blob){toast('Não foi possível guardar este instante.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='clareira-mundo.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Um instante da clareira foi guardado.');},'image/png');};
function drop(x,z){if(!engine||!insideLake(x,z))return;waves=addSources(pruneWaves(waves,time),createSources(x,z,time,state));if(paused)setPaused(false);engine.upload();status();$('hint').classList.add('hidden');}
$('scene').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();engine?.tapCenter();}});addEventListener('keydown',event=>{if(event.target.closest('input,select,button,dialog')||event.ctrlKey||event.metaKey||event.altKey)return;if(event.code==='Space'){event.preventDefault();setPaused(!paused);}if(event.code==='KeyH')$('home').click();});
async function initialize(){
 const THREE=await import('three'),{createNavigation}=await import('./navigation.js'),container=$('scene');
 const renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.shadowMap.autoUpdate=false;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;container.append(renderer.domElement);
 const scene=new THREE.Scene();scene.background=new THREE.Color(0xa1d5dc);scene.fog=new THREE.FogExp2(0xbcd9ce,.0021);const camera=new THREE.PerspectiveCamera(48,1,.15,2600);
 const hemisphere=new THREE.HemisphereLight(0xfff1d8,0x427846,1.8);scene.add(hemisphere);const moon=new THREE.DirectionalLight(0x91acff,.25);scene.add(moon);const sun=new THREE.DirectionalLight(0xffe0a0,3);sun.position.set(-70,125,-65);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-120,right:120,top:120,bottom:-120,far:330});sun.shadow.normalBias=.08;sun.shadow.bias=-.0002;scene.add(sun);
 $('loading').textContent='As colinas e a floresta estão ganhando forma…';await new Promise(resolve=>requestAnimationFrame(resolve));const grove=makeGrove(THREE,scene);const scenery=makeScenery(THREE,scene,grove.padSpots);const farms=makeFarms(THREE,scene);farms.update(0,0);const atmosphere=makeAtmosphere(THREE,scene);renderer.shadowMap.needsUpdate=true;const reflectionTarget=new THREE.WebGLCubeRenderTarget(256,{generateMipmaps:true,minFilter:THREE.LinearMipmapLinearFilter});const reflectionCamera=new THREE.CubeCamera(.1,2400,reflectionTarget);reflectionCamera.position.set(0,2,0);reflectionCamera.update(renderer,scene);const deer=makeDeer(THREE,scene,grove.trees);grove.occluders.push(...scenery.occluders,...farms.occluders,...deer.occluders);
 const uniforms={time:{value:0},count:{value:0},sources:{value:Array.from({length:MAX_WAVES},()=>new THREE.Vector4())},settings:{value:Array.from({length:MAX_WAVES},()=>new THREE.Vector2())},mistColor:{value:scene.fog.color},mistDensity:{value:scene.fog.density},environment:{value:reflectionTarget.texture},daylight:{value:1},sunDirection:{value:new THREE.Vector3(...daylightAt(0).sun)}};
 const water=new THREE.Mesh(new THREE.PlaneGeometry(LAKE.x*2,LAKE.z*2,384,288),new THREE.ShaderMaterial({vertexShader,fragmentShader,uniforms,side:THREE.DoubleSide}));water.rotation.x=-Math.PI/2;water.position.y=LAKE.level;scene.add(water);
 const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),-LAKE.level),hit=new THREE.Vector3();
 function tap(clientX,clientY){const bounds=container.getBoundingClientRect();pointer.set((clientX-bounds.left)/bounds.width*2-1,-(clientY-bounds.top)/bounds.height*2+1);camera.updateMatrixWorld();scene.updateMatrixWorld();raycaster.setFromCamera(pointer,camera);if(!raycaster.ray.intersectPlane(plane,hit)||!insideLake(hit.x,hit.z))return;
  // A hill, trunk or canopy in front of the lake must block the click.
  raycaster.far=raycaster.ray.origin.distanceTo(hit)-.05;const blockers=raycaster.intersectObjects(grove.occluders.filter(object=>object.visible),false);raycaster.far=Infinity;if(blockers.length)return;drop(hit.x,hit.z);
 }
 const navigation=createNavigation(THREE,camera,renderer.domElement,container,tap,explore);
 function upload(){uniforms.count.value=waves.length;waves.forEach((wave,i)=>{uniforms.sources.value[i].set(wave.x,wave.z,wave.time,wave.amplitude);uniforms.settings.value[i].set(wave.wavelength,wave.persistence);});}
 function render(){uniforms.time.value=time;renderer.render(scene,camera);}
 function resize(){const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();render();}
 engine={upload,render,navigation,canvas:renderer.domElement,tapCenter(){const b=container.getBoundingClientRect();tap(b.left+b.width/2,b.top+b.height/2);}};upload();resize();new ResizeObserver(resize).observe(container);$('loading').hidden=true;let last=performance.now(),lastPrune=0,cullClock=1,lastShadow=-10;const dayFog=new THREE.Color(0xbcd9ce),nightFog=new THREE.Color(0x101d35),daySky=new THREE.Color(0xfff1d8),nightSky=new THREE.Color(0x7388b4);
 renderer.setAnimationLoop(now=>{const delta=Math.min((now-last)/1000,.05);last=now;if(document.hidden)return;if(!$('about').open)navigation.update(delta);navigation.drawMap(delta);cullClock+=delta;if(cullClock>.3){grove.cull(camera);scenery.cull(camera);farms.cull(camera);cullClock=0;}const light=daylightAt(time+dayOffset);atmosphere.update(camera,reducedMotion?0:time,light);sun.position.set(...light.sun).multiplyScalar(180);sun.intensity=light.day*3;moon.position.copy(sun.position).multiplyScalar(-1);moon.intensity=light.night*.35;hemisphere.intensity=.22+light.day*1.58;hemisphere.color.copy(nightSky).lerp(daySky,light.day);scene.fog.color.copy(nightFog).lerp(dayFog,light.day);uniforms.daylight.value=light.day;uniforms.sunDirection.value.set(...light.sun);farms.update(reducedMotion?0:time,light.night);if(Math.abs(time+dayOffset-lastShadow)>2&&light.day>.05){renderer.shadowMap.needsUpdate=true;lastShadow=time+dayOffset;}const clockText=formatWorldTime(light.hours)+' · '+light.label;if($('world-clock').textContent!==clockText)$('world-clock').textContent=clockText;if(!paused){time+=delta;deer.update(delta,reducedMotion,camera);if(!reducedMotion){grove.update(time);scenery.update(time);}}if(time-lastPrune>.5){const filtered=pruneWaves(waves,time);if(filtered.length!==waves.length){waves=filtered;upload();status();}lastPrune=time;}render();});
 renderer.domElement.addEventListener('webglcontextlost',event=>{event.preventDefault();renderer.setAnimationLoop(null);navigation.controls.enabled=false;engine=null;$('loading').hidden=false;$('loading').textContent='A conexão gráfica foi interrompida. Recarregue para retornar à clareira.';});
}
initialize().catch(error=>{console.error(error);$('loading').hidden=false;$('loading').textContent='Não foi possível abrir o bosque. Verifique sua conexão e o suporte a WebGL 2 e recarregue a página.';$('render-status').textContent='VISUALIZAÇÃO INDISPONÍVEL';});
